KG42.register("clusters-9d2014f988c1bcf54f98111f",{"id":"43-operating_envelope_ev_market::v142-d-K001","paper":"43-operating_envelope_ev_market","label":"Determining the consumer role by net power.","record":{"cluster_id":"v142-d-K001","label":"Determining the consumer role by net power.","market_meaning":"Given a prosumer's net power in a certain period, its positive-value condition is used to determine the consumer role; this determination itself does not constitute market access or a trading obligation.","mechanism_ids":["v141-a-M02-prosumer-energy-management"],"market_types":["LEM"],"process_stages":["participation"],"scope_disposition":"compatible","scope_explanation":"The scope is limited to the definition of the consumer set under given net power and does not extend to producer classification, asset dispatch, or DOE sign determination.","assembly_status":"assembled","boundary_rationale":"Role determination has an explicit input, a determination activity, and a set-membership result, and can stand independently; it is retained separately from trading permission to avoid interpreting an operating state as an access threshold.","chain_bindings":[{"chain_id":"v141-c-R002","ownership":"primary","role":"core","rationale":"Provide the time-varying determination condition for the consumer role and the corresponding net-power object."}],"connections":[],"object_mappings":[],"gaps":[{"gap_id":"v142-d-K001-G01","category":"unverified_source","description":"The source transcription of the consumer set has not yet undergone independent verification; this cluster is only a candidate assembly permitted by the experiment.","chain_ids":["v141-c-R002"],"object_refs":["v141-c-R002::x::v141-c-R002-x-P","v141-c-R002::phi::v141-c-R002-C001"],"evidence_ids":["v141-b-g01-E13"],"proposal_ids":[],"required_work":"Manually verify the set conditions, indices, and net-power semantics; retain the currently frozen object, and do not describe candidate status as confirmation of source or scientific correctness."}]},"rule_refs":["43-operating_envelope_ev_market::v141-c-R002"],"unresolved_rule_refs":[],"node_ids":["COMP-440139830bbd658e"]});
